/* ==== @keyframes ==== */
@keyframes k-button-pulsing { 
  0% { opacity: 1; }
  50% { opacity: 0.4; }
  100% { opacity: 1; }
}
@keyframes ripple { 
  0% { transform: translate(-50%, -50%) scale(0); }
  20% { transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1); }
}
@keyframes pulsing-2-segment { 
  0% { transform: scale(1); }
  50% { transform: scale(1.5); }
  100% { transform: scale(1); }
}
@keyframes spinner-3-segment { 
  0% { inset-block-start: 0px; inset-inline-start: 50%; }
  33.3333% { inset-block-start: 100%; inset-inline-start: 0px; }
  66.6666% { inset-block-start: 100%; inset-inline-start: 100%; }
  100% { inset-block-start: 0px; inset-inline-start: 50%; }
}
@keyframes spinner-4-segment-1 { 
  0% { top: 50%; left: 50%; transform: translateX(-50%) translateY(-50%); }
  33.3% { top: 0px; left: 0px; transform: translateX(0px) translateY(0px); }
  66.6% { top: 0px; left: 0px; transform: translateX(0px) translateY(0px); }
  100% { top: 50%; left: 50%; transform: translateX(-50%) translateY(-50%); }
}
@keyframes spinner-4-segment-2 { 
  0% { top: 50%; left: 50%; transform: translateX(-50%) translateY(-50%); }
  33.3% { top: 0px; left: 100%; transform: translateX(-100%) translateY(0px); }
  66.6% { top: 0px; left: 100%; transform: translateX(-100%) translateY(0px); }
  100% { top: 50%; left: 50%; transform: translateX(-50%) translateY(-50%); }
}
@keyframes spinner-4-segment-3 { 
  0% { top: 50%; left: 50%; transform: translateX(-50%) translateY(-50%); }
  33.3% { top: 100%; left: 100%; transform: translateX(-100%) translateY(-100%); }
  66.6% { top: 100%; left: 100%; transform: translateX(-100%) translateY(-100%); }
  100% { top: 50%; left: 50%; transform: translateX(-50%) translateY(-50%); }
}
@keyframes spinner-4-segment-4 { 
  0% { top: 50%; left: 50%; transform: translateX(-50%) translateY(-50%); }
  33.3% { top: 100%; left: 0px; transform: translateX(0px) translateY(-100%); }
  66.6% { top: 100%; left: 0px; transform: translateX(0px) translateY(-100%); }
  100% { top: 50%; left: 50%; transform: translateX(-50%) translateY(-50%); }
}
@keyframes spinner-4 { 
  0% { transform: rotate(0deg); }
  33.3% { transform: rotate(0deg); }
  66.6% { transform: rotate(180deg); }
  100% { transform: rotate(180deg); }
}
@keyframes k-loading-animation { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@keyframes k-skeleton-wave { 
  0% { transform: translateX(-100%); }
  60% { transform: translateX(100%); }
  100% { transform: translateX(100%); }
}
@keyframes k-skeleton-pulse { 
  0% { opacity: 1; }
  50% { opacity: 0.4; }
  100% { opacity: 1; }
}
